/* generated by gen_maint_time.sh from main/maint.c */
#include <time.h>
time_t maint_next_time(time_t now, int hour, int minute, time_t last, int min_gap_s)
{
    struct tm tm;
    localtime_r(&now, &tm);
    tm.tm_hour = hour;
    tm.tm_min = minute;
    tm.tm_sec = 0;
    tm.tm_isdst = -1;
    time_t t = mktime(&tm);
    while (t <= now || (last && t - last < min_gap_s))
    {
        tm.tm_mday++;
        tm.tm_hour = hour;
        tm.tm_min = minute;
        tm.tm_isdst = -1;
        t = mktime(&tm);
    }
    return t;
}
